// La anti-repetición general (misma alerta en 10 min) la hace Enviar_Alerta.
// n8n devuelve un ítem vacío cuando la consulta no trae filas: se filtra por una columna clave.
// D6: UPDATE masivo sin WHERE (> 50 filas por ejecución). Una alerta por consulta detectada.
const tablaDe = (q, verbo) => {
  const re = verbo === 'DELETE' ? /^\s*delete\s+from\s+(?:only\s+)?([\w."]+)/i : /^\s*update\s+(?:only\s+)?([\w."]+)/i;
  return ((String(q).match(re) || [])[1] || 'desconocida').replace(/"/g, '');
};
const filas = $input.all().map(i => i.json).filter(r => r.queryid);
return filas.map(r => ({ json: {
  codigo: 'D6',
  severidad: 'CRÍTICA',
  tipo: 'UPDATE masivo sin WHERE detectado',
  tabla: tablaDe(r.query, 'UPDATE'),
  detalle: `Filas modificadas: ${r.filas_por_ejecucion} por ejecución (umbral: 50). Ejecuciones: ${r.calls}. queryid ${r.queryid}`,
  query: r.query,
  usuario: r.usuario,
  accion: 'Verificar intención. Consultar auditoria_datos (valor_antes / valor_nuevo) para revertir.'
}}));
